def main():
    path = ROOT / "content" / "stolenvalour.json"
    bank = [s for s in json.load(open(path, encoding="utf-8")) if not (s["id"] >= "sv-091" and s["id"] <= "sv-120")]
    assert len(T) == 30, len(T)
    for k, (hs, hw, hsc, lines, cta, cap, tag) in enumerate(T):
        dm = cta is DM
        tail = " DM us the word SITE on Instagram for a free homepage mock-up, no obligation." if dm else " WhatsApp 065 027 6518 for a free homepage mock-up, no obligation."
        bank.append({"id": f"sv-{91 + k:03d}", "pillar": "teach", "visual": "type",
                     "hook": {"say": hs, "show": hw, "scene": hsc},
                     "lines": [{"say": a, "show": b, "scene": c} for a, b, c in lines],
                     "cta": dict(cta), "caption": cap + tail, "hashtags": TAGS[:8] + [tag]})
    text = json.dumps(bank, ensure_ascii=False)
    assert chr(0x2014) not in text and chr(0x2013) not in text, "dash found"
    save(path, bank)
    print(len(bank), "scripts")


if __name__ == "__main__":
    main()
